        "message": "File exists" if os.path.exists("outputs/t01_selected_indicators.csv") else "File is missing"
    },
    {
        "check_name": "t05_clean_stops.csv is not empty",
        "passed": os.path.getsize("outputs/t05_clean_stops.csv") > 0,
