    },
    {
        "check_name": "t08_pois_clean.csv exists",
        "passed": os.path.exists("outputs/t08_pois_clean.csv"),
        "message": "File exists" if os.path.exists("outputs/t08_pois_clean.csv") else "File is missing"
    },
    {
        "check_name": "t10_accessibility_scores.csv is not empty",
        "passed": os.path.getsize("outputs/t10_accessibility_scores.csv") > 0,
        "message": "File is not empty" if os.path.getsize("outputs/t10_accessibility_scores.csv") > 0 else "File is empty"
    },
    {
        "check_name": "t13_city_clusters.csv exists",
        "passed": os.path.exists("outputs/t13_city_clusters.csv"),
        "message": "File exists" if os.path.exists("outputs/t13_city_clusters.csv") else "File is missing"
    }
]

# Run validation checks and write summary to outputs/t14_validation_summary.json
with open("outputs/t14_validation_summary.json", "w") as f:
